      finalizeGateContractPrompt,
      contains('time-left notices report the remaining budget'),
    );
    expect(
      finalizeGateContractPrompt,
      contains('the next compliant action is another approach'),
    );
    expect(
      finalizeGateContractPrompt,
      contains('you are interrupted automatically when time expires'),
    );
